import{_ as e,o as d,c as o,ae as r}from"./chunks/framework.DYeE-XvM.js";const u=JSON.parse('{"title":"项目结构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/project-structure.md","filePath":"guide/project-structure.md","lastUpdated":null}'),a={name:"guide/project-structure.md"};function c(s,t,h,i,l,n){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h1><p>本文按源码目录说明 <code>xymj-colyseus-server</code> 的主要模块职责，便于对照仓库阅读与二次开发。</p><h2 id="入口与-colyseus-配置" tabindex="-1">入口与 Colyseus 配置 <a class="header-anchor" href="#入口与-colyseus-配置" aria-label="Permalink to &quot;入口与 Colyseus 配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>src/index.ts</code></td><td>进程入口：加载 <code>reflect-metadata</code>、安装控制台日志前缀、调用 <code>@colyseus/tools</code> 的 <code>listen(app)</code>。</td></tr><tr><td><code>src/app.config.ts</code></td><td>Colyseus + Express 一体化配置：注册房间、静态资源、routing-controllers、Swagger、Playground（非生产）、Monitor、数据库与 Redis 初始化。</td></tr></tbody></table><p>在 <code>app.config.ts</code> 的 <code>initializeGameServer</code> 中注册的 <strong>房间名（客户端 <code>joinOrCreate</code> 使用）</strong> 包括：</p><table tabindex="0"><thead><tr><th>房间名</th><th>类</th><th>用途</th></tr></thead><tbody><tr><td><code>my_room</code></td><td><code>MyRoom</code></td><td>示例 / 模板房间</td></tr><tr><td><code>game_room</code></td><td><code>GameRoom</code></td><td>帧同步对局房（匹配成功后进入）</td></tr><tr><td><code>matchmaker_room</code></td><td><code>MatchmakerRoom</code></td><td>匹配与组队（主动排队 / 房间码开房）</td></tr><tr><td><code>chat_world_room</code> 等</td><td><code>WorldChatRoom</code> 等</td><td>世界 / 工会 / 附近 / 队伍聊天</td></tr><tr><td><code>loadtest_room</code></td><td><code>LoadTestRoom</code></td><td>无 JWT 的并发压测房（仅测试）</td></tr></tbody></table><h2 id="http-与中间件" tabindex="-1">HTTP 与中间件 <a class="header-anchor" href="#http-与中间件" aria-label="Permalink to &quot;HTTP 与中间件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>src/controllers/</code></td><td>装饰器控制器：<code>LoginController</code>、<code>AuthController</code>、<code>HealthController</code>、小游戏相关接口等；<code>autoLoad/index.ts</code> 聚合导出供 <code>useExpressServer</code> 使用。</td></tr><tr><td><code>src/middleware/</code></td><td><code>auth.middleware</code>、<code>validation.middleware</code>、<code>error.middleware</code>、<code>decorator.middleware</code>。</td></tr><tr><td><code>src/routes/index.ts</code></td><td>API 路由前缀等集中配置。</td></tr><tr><td><code>src/dto/</code></td><td>请求体验证 DTO（如认证）。</td></tr></tbody></table><h2 id="业务服务与数据" tabindex="-1">业务服务与数据 <a class="header-anchor" href="#业务服务与数据" aria-label="Permalink to &quot;业务服务与数据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>src/services/</code></td><td><code>AuthService</code>、<code>AccessTokenAndLoginService</code>、<code>matchmaking/MatchmakingService</code>（Redis 队列与房间队伍）等。</td></tr><tr><td><code>src/models/</code>、<code>src/database/</code></td><td>TypeORM 实体与数据库连接。</td></tr><tr><td><code>src/utils/redis.ts</code></td><td>Redis 单例，供匹配、聊天跨实例、重连键等使用。</td></tr><tr><td><code>src/utils/jwt.ts</code></td><td>JWT 签发与校验。</td></tr></tbody></table><h2 id="房间与-schema" tabindex="-1">房间与 Schema <a class="header-anchor" href="#房间与-schema" aria-label="Permalink to &quot;房间与 Schema&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>src/rooms/schema/</code></td><td>Colyseus Schema 状态定义（如 <code>MyRoomState</code>、聊天相关 Schema）。</td></tr><tr><td><code>src/rooms/chat/</code></td><td><code>BaseChatRoom</code> 及四类频道房间；世界频道通过 Redis Pub/Sub 跨进程同步。</td></tr><tr><td><code>src/utils/FrameSync.ts</code></td><td><code>FrameSyncManager</code> 与 <code>FrameSyncRoom</code> 基类，供 <code>GameRoom</code> 做固定帧率逻辑与 <code>input</code> 消息处理。</td></tr><tr><td><code>src/utils/decorators/RequireAuth.ts</code></td><td>房间方法鉴权装饰器（JWT）。</td></tr></tbody></table><h2 id="配置与文档相关" tabindex="-1">配置与文档相关 <a class="header-anchor" href="#配置与文档相关" aria-label="Permalink to &quot;配置与文档相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>src/config/</code></td><td>应用端口、Colyseus ping、Swagger、小游戏等配置入口。</td></tr><tr><td><code>loadtest/</code></td><td>压测脚本示例。</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/xcs.github.io/guide/configuration.html">配置说明</a></li><li><a href="/xcs.github.io/rooms/overview.html">房间机制概览</a></li><li><a href="/xcs.github.io/rooms/matchmaking.html">匹配与开房</a></li><li><a href="/xcs.github.io/rooms/frame-sync-game-room.html">帧同步与游戏房</a></li></ul>',16)])])}const b=e(a,[["render",c]]);export{u as __pageData,b as default};
